actions.script:
identityList = []
const accounts = ec.service.sync().name('org.moqui.mail.EmailClientServices.get#UserEmailAccounts').call()
if (ec.message.hasError()) return
const partyId = ec.user.userAccount?.partyId || null
let name = ec.user.userAccount?.userFullName || ec.user.username
if (partyId) {
    const detail = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).disableAuthz().one()
    if (detail) name = detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ') || name
}
me = {userId: ec.user.userId, partyId: partyId, name: name}
defaultValue = null
for (const account of Array.from(accounts.accountList || [])) {
    if (account.isInternal || !account.canSend) continue
    const identities = Array.from(account.identityList || [])
    if (identities.length === 0) identityList.push({value: 'account:' + account.emailAccountId, label: `${account.accountName || account.emailAddress} <${account.emailAddress}>`,
        emailAccountId: account.emailAccountId, emailIdentityId: null, emailAddress: account.emailAddress, displayName: account.accountName ?? null,
        accountName: account.accountName ?? null, signatureHtml: null, signaturePlacementEnumId: null, useForReplies: false, isDefault: true})
    for (const identity of identities) identityList.push({value: 'identity:' + identity.emailIdentityId,
        label: identity.displayName ? `${identity.displayName} <${identity.emailAddress}>` : identity.emailAddress,
        emailAccountId: account.emailAccountId, emailIdentityId: identity.emailIdentityId, emailAddress: identity.emailAddress,
        displayName: identity.displayName ?? null, accountName: account.accountName ?? null, signatureHtml: identity.signatureHtml ?? null,
        signaturePlacementEnumId: identity.signaturePlacementEnumId ?? null, useForReplies: identity.useForReplies === true, isDefault: identity.isDefault === true})
    if (!defaultValue) {
        const mine = identityList.filter((item) => item.emailAccountId === account.emailAccountId)
        defaultValue = (mine.find((item) => item.isDefault) || mine[0]).value
    }
}
if (partyId) identityList.push({value: 'internal', label: ec.l10n.localize('Internal message') + ' (' + name + ')', emailAccountId: null,
    emailIdentityId: null, emailAddress: null, displayName: name, accountName: ec.l10n.localize('Internal'), signatureHtml: null,
    signaturePlacementEnumId: null, useForReplies: false, isDefault: false, isInternal: true})
if (!defaultValue) defaultValue = partyId ? 'internal' : null
const preferred = String(ec.user.getPreference('MAIL_DEFAULT_ACCOUNT') || '').trim()
if (preferred) {
    const mine = identityList.filter((item) => item.emailAccountId === preferred)
    if (mine.length) defaultValue = (mine.find((item) => item.isDefault) || mine[0]).value
}

const MAIL = 'org.moqui.mail.EmailClientServices'
const L = (text) => ec.l10n.localize(text)
const escape = (text) => String(text ?? '').replace(/[<>&"]/g, (ch) => ({'<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;'})[ch])
const splitAddresses = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { if (current.trim()) out.push(current.trim()); current = ''; continue }
        current += ch
    }
    if (current.trim()) out.push(current.trim())
    return out.map((entry) => {
        const match = /^(.*)<([^>]+)>\s*$/.exec(entry)
        if (!match) return {address: entry.replace(/^mailto:/i, '').replace(/^"|"$/g, '').trim(), name: null}
        const name = match[1].trim().replace(/^"(.*)"$/, '$1').trim()
        return {address: match[2].trim(), name: name || null}
    })
}
const addressChip = (entry) => ({value: entry.name ? `"${String(entry.name).replace(/"/g, '')}" <${entry.address}>` : entry.address,
    label: entry.name ? `${entry.name} <${entry.address}>` : entry.address, kind: 'address', locked: false})
const toMillis = (value) => value == null || value === '' ? null : (typeof value === 'number' ? value : Number(value))
const dateText = (millis) => millis ? ec.l10n.format(new Date(millis), 'EEE, MMM d, yyyy h:mm a') : ''
const ids = ec.service.sync().name('ironstone.comms.ComposeServices.get#Identities').call()
if (ec.message.hasError()) return
const identities = Array.from(ids.identityList || [])
const prefUndo = ec.user.getPreference('MAIL_UNDO_SECONDS')
const placement = ec.user.getPreference('MAIL_SIGNATURE_PLACEMENT')
const result = {identityList: identities, fromValue: ids.defaultValue, me: ids.me, to: [], cc: [], bcc: [], subject: '', body: '', quoteHtml: null,
    emailMessageId: null, parentEmailMessageId: null, isForward: false, parentCommEventId: null, replyToSenderOnly: false, contactListId: null,
    contactListName: null, record: null, attachmentList: [], undoSeconds: prefUndo != null && prefUndo !== '' ? Number(prefUndo) : 10,
    signaturePlacement: placement === 'below' ? 'below' : 'above', threadStore: null, threadId: null, kind: 'new'}
const identityFor = (accountId, addresses) => {
    const wanted = new Set(Array.from(addresses || []).map((address) => String(address || '').toLowerCase()))
    const mine = identities.filter((item) => item.emailAccountId === accountId)
    return (mine.find((item) => item.emailAddress && wanted.has(String(item.emailAddress).toLowerCase())) || mine.find((item) => item.isDefault) || mine[0] || null)
}
const myAddresses = new Set(identities.filter((item) => item.emailAddress).map((item) => String(item.emailAddress).toLowerCase()))
if (ec.user.userAccount?.emailAddress) myAddresses.add(String(ec.user.userAccount.emailAddress).toLowerCase())
const headerValue = (headers, name) => {
    let found = null
    for (const line of String(headers || '').split(/\r?\n/)) {
        if (found != null) { if (/^[ \t]/.test(line)) { found += ' ' + line.trim(); continue } break }
        const colon = line.indexOf(':')
        if (colon > 0 && line.substring(0, colon).trim().toLowerCase() === String(name).toLowerCase()) found = line.substring(colon + 1).trim()
    }
    return found
}
// the quoted part of a reply or forward: the message cleaned to the safe set, apart from the editor
const quoteOf = (message, forward) => {
    const fromText = message.fromName ? `${message.fromName} <${message.fromAddress}>` : (message.fromAddress || '')
    const html = message.body && /<[a-z]/i.test(message.body) ? StringUtilities.cleanHtml(message.body)
            : '<p>' + escape(message.bodyText || message.body || '').replace(/\n/g, '<br>') + '</p>'
    if (forward) return `<div class="ironstone-quote"><p>---------- ${escape(L('Forwarded message'))} ---------<br>${escape(L('From'))}: ${escape(fromText)}<br>` +
        `${escape(L('Date'))}: ${escape(dateText(toMillis(message.messageDate)))}<br>${escape(L('Subject'))}: ${escape(message.subject || '')}<br>` +
        `${escape(L('To'))}: ${escape(message.toAddresses || '')}</p>${html}</div>`
    return `<div class="ironstone-quote"><p>${escape(ec.resource.expand('On ${date}, ${name} wrote:', '', {date: dateText(toMillis(message.messageDate)), name: fromText}))}</p>` +
        `<blockquote>${html}</blockquote></div>`
}
const splitQuote = (html) => {
    const text = String(html || '')
    const at = text.indexOf('<div class="ironstone-quote">')
    return at < 0 ? {body: text, quote: null} : {body: text.substring(0, at), quote: text.substring(at)}
}
const threadMessage = (emailId, headers) => {
    const out = ec.service.sync().name(MAIL + '.get#Thread').parameters({emailMessageId: emailId, includeHeaders: headers === true}).requireNewTransaction(true).call()
    if (ec.message.hasError()) return null
    return {thread: out, message: Array.from(out.messageList || []).find((item) => item.emailMessageId === emailId)}
}
const fileList = (emailId) => Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailId)
        .orderBy('emailMessageAttachmentId').list()).map((file) => ({id: file.emailMessageAttachmentId, name: file.fileName || 'attachment',
            size: file.fileSize ?? null, contentType: file.contentType ?? null}))

if (emailMessageId) {
    // a draft of the user's
    const found = threadMessage(emailMessageId, false)
    if (found == null) return
    const draft = found.message
    if (draft.statusId !== 'ES_DRAFT' && !(draft.statusId === 'ES_READY' && draft.sendError)) { ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
    if (!draft.canSend) { ec.message.addError(`You may not send from email account ${draft.emailAccountId}`); return }
    const identity = (draft.emailIdentityId && identities.find((item) => item.emailIdentityId === draft.emailIdentityId)) || identityFor(draft.emailAccountId, [draft.fromAddress])
    if (identity) result.fromValue = identity.value
    result.to = splitAddresses(draft.toAddresses).map(addressChip)
    result.cc = splitAddresses(draft.ccAddresses).map(addressChip)
    result.bcc = splitAddresses(draft.bccAddresses).map(addressChip)
    result.subject = draft.subject || ''
    const parts = splitQuote(draft.body || (draft.bodyText ? '<p>' + escape(draft.bodyText).replace(/\n/g, '<br>') + '</p>' : ''))
    result.body = parts.body
    result.quoteHtml = parts.quote
    result.emailMessageId = emailMessageId
    result.parentEmailMessageId = draft.parentEmailMessageId
    result.isForward = !!draft.parentEmailMessageId && !draft.inReplyTo
    result.attachmentList = fileList(emailMessageId)
    result.kind = 'draft'
    // the client's own reference of the draft (save#ComposeDraft clientRef), so a client that edits it offline queues its send by it
    const stored = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).selectField('clientRef')
            .selectField('messageDate').disableAuthz().one()
    result.clientRef = stored?.clientRef ?? null
    // the stamp of its last save, which a save from this copy gives back (baseStamp) so one made elsewhere since is not overwritten
    result.draftStamp = stored?.messageDate == null ? null : (typeof stored.messageDate.getTime === 'function' ? stored.messageDate.getTime() : Number(stored.messageDate))
    if (draft.rootEmailMessageId) { result.threadStore = 'email'; result.threadId = draft.rootEmailMessageId }
    const record = ec.entity.find('mantle.party.communication.EmailMessageRecord').condition('emailMessageId', emailMessageId).disableAuthz().list()[0]
    if (record) { recordEntity = record.recordEntityName; recordId = record.recordId }
} else if (replyToEmailMessageId || forwardEmailMessageId) {
    const parentId = replyToEmailMessageId || forwardEmailMessageId
    const forward = !replyToEmailMessageId
    const found = threadMessage(parentId, true)
    if (found == null) return
    const parent = found.message
    const recipients = splitAddresses(parent.toAddresses).concat(splitAddresses(parent.ccAddresses))
    // from the account it came to when the user may send from it, else the default
    const sendable = identities.filter((item) => !item.isInternal && item.emailAccountId === parent.emailAccountId)
    const identity = sendable.length ? identityFor(parent.emailAccountId, recipients.map((entry) => entry.address)) : null
    if (identity) result.fromValue = identity.value
    else if (!identities.some((item) => !item.isInternal)) { ec.message.addError(L('Add a mail account to send email')); return }
    const subjectText = parent.subject || ''
    result.subject = forward ? (/^fwd?:/i.test(subjectText) ? subjectText : 'Fwd: ' + subjectText) : (/^re:/i.test(subjectText) ? subjectText : 'Re: ' + subjectText)
    result.quoteHtml = quoteOf(parent, forward)
    result.parentEmailMessageId = parentId
    result.isForward = forward
    result.threadStore = 'email'
    result.threadId = found.thread.rootEmailMessageId
    if (!forward) {
        const fromMe = myAddresses.has(String(parent.fromAddress || '').toLowerCase())
        const replyTo = splitAddresses(headerValue(parent.headersString, 'Reply-To'))
        const sender = replyTo.length ? replyTo : [{address: parent.fromAddress, name: parent.fromName}]
        const notMe = (entry) => !myAddresses.has(String(entry.address || '').toLowerCase())
        let toList = fromMe ? splitAddresses(parent.toAddresses) : sender
        let ccList = []
        if (replyAll) {
            toList = toList.concat(fromMe ? [] : splitAddresses(parent.toAddresses).filter(notMe))
            ccList = splitAddresses(parent.ccAddresses).filter(notMe)
        }
        const seen = new Set()
        const unique = (list) => list.filter((entry) => { const key = String(entry.address || '').toLowerCase(); if (!key || seen.has(key)) return false; seen.add(key); return true })
        result.to = unique(toList).map(addressChip)
        result.cc = unique(ccList).map(addressChip)
        result.kind = replyAll ? 'replyAll' : 'reply'
    } else {
        // the forward is a draft now, so the files go with it as copies of their own
        if (!identity && !result.fromValue) { ec.message.addError(L('Add a mail account to send email')); return }
        const chosen = identities.find((item) => item.value === result.fromValue)
        if (!chosen || chosen.isInternal) { ec.message.addError(L('Add a mail account to send email')); return }
        const draft = ec.service.sync().name(MAIL + '.save#Draft').parameters({emailAccountId: chosen.emailAccountId, emailIdentityId: chosen.emailIdentityId,
            parentEmailMessageId: parentId, isForward: true, subject: result.subject, body: '<p></p>' + result.quoteHtml}).call()
        if (ec.message.hasError()) return
        const files = []
        for (const file of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', parentId).list()) {
            if (!file.attachmentLocation || file.isInline === 'Y') continue
            const safe = String(file.fileName || 'attachment').replace(/[\/\\?#%:]/g, '_')
            const location = `dbresource://email/${chosen.emailAccountId}/${draft.emailMessageId}/${files.length + 1}-${safe}`
            try {
                ec.resource.getLocationReference(location).copyFrom(file.attachmentLocation)
                files.push({attachmentLocation: location, fileName: file.fileName, fileSize: file.fileSize, contentType: file.contentType})
            } catch (err) { ec.logger.warn(`Forward of ${parentId}: the file ${file.fileName} was not copied: ${err && err.message ? err.message : err}`) }
        }
        if (files.length) {
            ec.service.sync().name(MAIL + '.save#Draft').parameters({emailMessageId: draft.emailMessageId, attachmentList: files}).call()
            if (ec.message.hasError()) return
        }
        result.emailMessageId = draft.emailMessageId
        result.attachmentList = fileList(draft.emailMessageId)
        result.kind = 'forward'
    }
} else if (replyToCommEventId) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', replyToCommEventId).disableAuthz().one()
    if (event == null) { ec.message.addError(`Communication event ${replyToCommEventId} not found`); return }
    if (event.communicationEventTypeId === 'Email') {
        // Chatter's Reply by email: the email must be on the record, which the user must see
        if (event.emailMessageId) {
            const found = threadMessage(event.emailMessageId, false)
            if (found != null) {
                replyToEmailMessageId = event.emailMessageId
                const again = ec.service.sync().name('ironstone.comms.ComposeServices.get#ComposeData').parameters({replyToEmailMessageId: event.emailMessageId,
                    replyAll: replyAll, recordEntity: recordEntity, recordId: recordId}).call()
                if (ec.message.hasError()) return
                compose = again.compose
                return
            }
            ec.message.clearErrors()
        }
        if (!recordEntity || !recordId) { ec.message.addError(`Communication event ${replyToCommEventId} not found`); return }
        const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: recordEntity, recordId: recordId,
            requireVisible: true}).call()
        if (ec.message.hasError()) return
        ec.service.sync().name('ironstone.shared.ChatterServices.check#CommEventOnRecord').parameters({info: info.info, recordId: recordId,
            communicationEventId: replyToCommEventId}).call()
        if (ec.message.hasError()) return
        // an email of the record with no mail client message: to its sender's address
        const otherId = event.fromPartyId === ec.user.userAccount?.partyId ? event.toPartyId : event.fromPartyId
        const address = otherId ? ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameter('partyId', otherId).call()?.emailAddress : null
        ec.message.clearErrors()
        if (address) {
            const detail = ec.entity.find('mantle.party.PartyDetail').condition('partyId', otherId).disableAuthz().one()
            const name = detail ? (detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ')) : null
            result.to = [addressChip({address: address, name: name})]
        }
        const subjectText = event.subject || ''
        result.subject = /^re:/i.test(subjectText) ? subjectText : 'Re: ' + subjectText
        const quoted = /<[a-z]/i.test(event.body || '') ? StringUtilities.cleanHtml(event.body) : '<p>' + escape(event.body || '').replace(/\n/g, '<br>') + '</p>'
        result.quoteHtml = `<div class="ironstone-quote"><p>${escape(ec.resource.expand('On ${date}, ${name} wrote:', '', {date: dateText(toMillis(event.entryDate)),
            name: result.to.length ? result.to[0].label : ''}))}</p><blockquote>${quoted}</blockquote></div>`
        result.kind = 'reply'
    } else {
        // an internal reply: reply#CommunicationEvent keeps the thread's recipients (or the mailbox)
        const out = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThread').parameter('communicationEventId', replyToCommEventId).call()
        if (ec.message.hasError()) return
        const parent = Array.from(out.messageList || []).find((item) => item.communicationEventId === replyToCommEventId)
        const names = {}
        for (const participant of Array.from(out.participantList || [])) names[participant.partyId] = participant.name
        const myPartyId = ec.user.userAccount?.partyId
        const chip = (id) => ({value: 'party:' + id, label: names[id] || id, kind: 'party', locked: true})
        result.fromValue = 'internal'
        result.parentCommEventId = replyToCommEventId
        result.replyToSenderOnly = replyToSender === true
        result.threadStore = 'internal'
        result.threadId = out.rootCommEventId
        if (out.isClosed && !replyToSender) { ec.message.addError(L('This thread is closed')); return }
        if (out.contactListId && !replyToSender) {
            if (!out.canReply) { ec.message.addError(ec.resource.expand('You may not post to mailbox ${name}', '', {name: out.contactListName || out.contactListId})); return }
            result.contactListId = out.contactListId
            result.contactListName = out.contactListName
            result.to = [{value: 'list:' + out.contactListId, label: out.contactListName || out.contactListId, kind: 'mailbox', locked: true}]
        } else if (replyToSender) {
            const other = parent.fromPartyId === myPartyId ? parent.toPartyId : parent.fromPartyId
            if (other) result.to = [chip(other)]
        } else {
            const to = [parent.fromPartyId, parent.toPartyId].concat(Array.from(parent.toPartyIdList || [])).filter((id) => id && id !== myPartyId)
            const cc = Array.from(parent.ccPartyIdList || []).filter((id) => id && id !== myPartyId && !to.includes(id))
            result.to = Array.from(new Set(to)).map(chip)
            result.cc = Array.from(new Set(cc)).map(chip)
        }
        const subjectText = parent.subject || out.subject || ''
        result.subject = /^re:/i.test(subjectText) ? subjectText : 'Re: ' + subjectText
        result.kind = replyToSender ? 'replySender' : 'reply'
    }
} else {
    // a new message: mailto-style values, a mailbox to post to
    for (const [field, text] of [['to', to], ['cc', cc], ['bcc', bcc]]) result[field] = splitAddresses(text).filter((entry) => entry.address).map(addressChip)
    if (subject) result.subject = String(subject)
    if (body) result.body = /<[a-z]/i.test(String(body)) ? StringUtilities.cleanHtml(String(body)) : '<p>' + escape(body).replace(/\n/g, '<br>') + '</p>'
    if (contactListId) {
        const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess').parameter('contactListId', contactListId).call()
        if (ec.message.hasError()) return
        if (!access.exists || !access.isMailbox || !access.canSeeHeader) { ec.message.addError(`Mailbox ${contactListId} not found`); return }
        if (!access.canPost) { ec.message.addError(ec.resource.expand('You may not post to mailbox ${name}', '', {name: access.contactList?.contactListName || contactListId})); return }
        result.fromValue = 'internal'
        result.contactListId = contactListId
        result.contactListName = access.contactList?.contactListName || contactListId
        result.to = [{value: 'list:' + contactListId, label: result.contactListName, kind: 'mailbox', locked: false}]
    }
}
// the record chip: one the user sees
if (recordEntity && recordId) {
    const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: recordEntity, recordId: recordId}).call()
    ec.message.clearErrors()
    if (info && info.visible) result.record = {recordEntityName: info.info?.recordEntityName || recordEntity, recordId: recordId, title: info.title || recordId,
        typeLabel: info.typeLabel || null, icon: info.icon || 'sym_o_link', url: info.url || null}
}
compose = result

const cf = ec.entity.conditionFactory
optionList = []
const text = String(term || '').trim()
const max = Math.max(1, Math.min(limit || 12, 50))
const like = (field) => cf.makeCondition(field, 'like', `%${text}%`, false, true)
if (mode === 'internal') {
    const users = ec.service.sync().name('ironstone.shared.ChatterServices.search#Users').parameters({term: text, limit: max}).requireNewTransaction(true).call()
    ec.message.clearErrors()
    for (const user of Array.from(users?.userList || [])) if (user.partyId) optionList.push({value: 'party:' + user.partyId, label: user.label, kind: 'party'})
    const lists = ec.service.sync().name('mantle.marketing.ContactListServices.find#ContactLists').parameters({contactListTypeEnumId: 'MAILBOX',
        searchText: text || null}).requireNewTransaction(true).call()
    ec.message.clearErrors()
    for (const list of Array.from(lists?.contactListList || [])) if (list.canPost) optionList.push({value: 'list:' + list.contactListId,
        label: list.contactListName, kind: 'mailbox'})
    optionList = optionList.slice(0, max)
    return
}
if (text.length < 1) return
const seen = new Set()
const add = (address, name) => {
    const key = String(address || '').trim().toLowerCase()
    if (!key.includes('@') || seen.has(key)) return
    seen.add(key)
    const clean = name ? String(name).replace(/"/g, '').trim() : null
    optionList.push({value: clean ? `"${clean}" <${String(address).trim()}>` : String(address).trim(), label: clean ? `${clean} <${String(address).trim()}>` : String(address).trim(), kind: 'address'})
}
const userId = ec.user.userId
const visible = cf.makeCondition([cf.makeCondition('privateOwnerUserId', 'equals', null), cf.makeCondition('privateOwnerUserId', 'equals', userId)], 'or')
// parties by name, with their email addresses
const parts = text.split(/\s+/).filter((part) => part)
const nameCondition = cf.makeCondition(parts.map((part) => cf.makeCondition([cf.makeCondition('firstName', 'like', `%${part}%`, false, true),
    cf.makeCondition('lastName', 'like', `%${part}%`, false, true), cf.makeCondition('organizationName', 'like', `%${part}%`, false, true)], 'or')), 'and')
// the parties are read with authorization on: the transition runs as the Comms app, so its entity filters
// (MANTLE_USER_ORG's organizations, MANTLE_PRIVATE_CONTACT) keep out what the user may not see, from either mount
const named = Array.from(ec.entity.find('mantle.party.PartyDetail').condition(nameCondition).condition(visible)
        .condition(cf.makeCondition('disabled', 'not-equals', 'Y', true)).selectField('partyId').selectField('firstName').selectField('lastName')
        .selectField('organizationName').limit(40).list())
const nameOf = (party) => party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ')
const names = {}
for (const party of named) names[party.partyId] = nameOf(party)
// and by address
const byAddress = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('contactMechTypeEnumId', 'CmtEmailAddress')
        .condition(like('infoString')).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('partyId').selectField('infoString')
        .limit(40).disableAuthz().list())
const addressParties = Array.from(new Set(byAddress.map((row) => row.partyId).filter((id) => !(id in names))))
if (addressParties.length) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', addressParties).condition(visible)
        .condition(cf.makeCondition('disabled', 'not-equals', 'Y', true)).list()) names[party.partyId] = nameOf(party)
const partyIds = Object.keys(names)
if (partyIds.length) for (const row of ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', 'in', partyIds)
        .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
        .selectField('partyId').selectField('infoString').disableAuthz().list()) {
    if (optionList.length >= max) break
    add(row.infoString, names[row.partyId])
}
// users of this system, by name or address
