    try {
        const out = ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call()
        return ec.message.hasError() ? {why: ec.message.getErrorsString()} : {out: out}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const item of Array.from(itemList || [])) {
    const label = item && item.path ? String(item.path).split('/').pop() : '?'
    ec.message.pushErrors()
    try {
        if (!item || !item.driveId || !item.path) throw new Error(L('No file chosen'))
        const found = own('org.moqui.resource.FileServices.get#ResourceInfo', {driveId: item.driveId, path: item.path, opened: true})
        if (!found.out || !found.out.resource) throw new Error(found.why || L('File not found'))
        const resource = found.out.resource
        if (resource.isDirectory || (resource.size != null && Number(resource.size) > Number(maxAttachBytes || 26214400))) {
            const made = own('org.moqui.resource.FileServices.share#Resource', {driveId: item.driveId, path: item.path,
                isLink: 'Y', permissionEnumId: 'RspView', linkLabel: L('Sent by email')})
            if (!made.out) throw new Error(resource.isDirectory ? L('A folder is sent as a link, and you may not share this one')
                    : L('Too large to attach, and you may not share it by link'))
            const link = made.out
            linkList.push({name: resource.name, linkPath: link.linkPath, size: resource.size ?? null, isDirectory: resource.isDirectory === true})
            continue
        }
        const location = draft ? `dbresource://email/${draft.emailAccountId}/${emailMessageId}/${token()}-${safe(resource.name)}`
                : `dbresource://ironstone/compose/${ec.user.userId}/${token()}/${safe(resource.name)}`
        const stream = ec.resource.getLocationReference(resource.location).openStream()
        try { ec.resource.getLocationReference(location).putStream(stream) } finally { if (stream && stream.close) stream.close() }
        const entry = {name: resource.name, size: resource.size ?? null, contentType: resource.contentType ?? null}
        if (draft) existing.push({attachmentLocation: location, fileName: resource.name, fileSize: resource.size ?? null, contentType: resource.contentType ?? null})
        else uploadList.push(Object.assign({location: location}, entry))
    } catch (err) {
        const why = err && err.message ? err.message : String(err)
        ec.logger.warn(`Attach from Files: ${label} not attached: ${why}`)
        failedList.push({name: label, error: why})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (draft) {
    if (existing.length > before) {
        ec.service.sync().name('org.moqui.mail.EmailClientServices.save#Draft').parameters({emailMessageId: emailMessageId, attachmentList: existing}).call()
        if (ec.message.hasError()) return
    }
    attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
            .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
                contentType: row.contentType ?? null}))
}

ec.service.sync().name('ironstone.comms.ComposeServices.check#DraftAccess').parameter('emailMessageId', emailMessageId).call()
if (ec.message.hasError()) return
const rows = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list())
const gone = rows.find((row) => row.emailMessageAttachmentId === emailMessageAttachmentId)
if (!gone) { ec.message.addError(ec.l10n.localize('Attachment not found') + ': ' + emailMessageAttachmentId); return }
const kept = rows.filter((row) => row !== gone).map((row) => ({attachmentLocation: row.attachmentLocation, fileName: row.fileName, fileSize: row.fileSize,
    contentType: row.contentType, contentId: row.contentId, isInline: row.isInline}))
ec.service.sync().name('org.moqui.mail.EmailClientServices.save#Draft').parameters({emailMessageId: emailMessageId, attachmentList: kept}).call()
if (ec.message.hasError()) return
if (String(gone.attachmentLocation || '').startsWith(`dbresource://email/`)) {
    try { ec.resource.getLocationReference(gone.attachmentLocation).delete() }
    catch (err) { ec.logger.warn(`The file ${gone.attachmentLocation} was not deleted: ${err}`) }
}
attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
        .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
            contentType: row.contentType ?? null}))

const L = (text) => ec.l10n.localize(text)
communicationEventIdList = []
sent = false
duplicate = false
conflict = false
compose = null
const partyId = ec.user.userAccount?.partyId || null
// the record chip: refused before anything goes when the user may not see it
let record = null
if (recordEntity && recordId) {
    const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: recordEntity, recordId: recordId,
        requireVisible: true}).call()
    if (ec.message.hasError()) return
    record = {recordEntityName: info.info?.recordEntityName || recordEntity, recordId: String(recordId), title: info.title || recordId}
}
if (fromValue !== 'internal') {
    mode = 'email'
    const saved = ec.service.sync().name('ironstone.comms.ComposeServices.save#ComposeDraft').parameters({emailMessageId: emailMessageId, fromValue: fromValue,
        toJson: toJson, ccJson: ccJson, bccJson: bccJson, subject: subject, body: body, bodyText: bodyText, quoteHtml: quoteHtml,
        parentEmailMessageId: parentEmailMessageId, isForward: isForward, strict: true, clientRef: clientRef || null, baseStamp: baseStamp ?? null,
        saveRef: saveRef || null}).call()
    if (ec.message.hasError()) return
    emailMessageId = saved.emailMessageId
    if (saved.conflict === true) {
        // saved elsewhere since the client's copy: not sent; the client keeps its own as a copy
        conflict = true
        compose = saved.compose || null
        message = L('Changed elsewhere since: not sent')
        return
    }
    if (saved.duplicate === true) {
        // a retry of a send that went through: its state as it is now, and nothing else is done
        const state = ec.service.sync().name('org.moqui.mail.EmailClientServices.get#SendState').parameter('emailMessageId', emailMessageId).call()
        if (ec.message.hasError()) return
        duplicate = true
        statusId = state.statusId; sent = state.sent === true; sendError = state.sendError ?? null
        scheduledSendDate = state.scheduledSendDate ?? null; message = state.message
        return
    }
    const hold = scheduledSendDate != null ? null : Math.max(0, Math.min(Number(holdSeconds || 0), 300))
    const parameters = {emailMessageId: emailMessageId, scheduledSendDate: scheduledSendDate, holdSeconds: hold}
    const out = record ? ec.service.sync().name('mantle.party.CommunicationServices.send#EmailDraft').parameters(Object.assign({
            recordEntityName: record.recordEntityName, recordId: record.recordId, notifyFollowers: true}, parameters)).call()
        : ec.service.sync().name('org.moqui.mail.EmailClientServices.send#Draft').parameters(parameters).call()
    if (ec.message.hasError()) return
    statusId = out.statusId
    sent = out.sent === true
    sendError = out.sendError ?? null
    scheduledSendDate = out.scheduledSendDate ?? null
    message = statusId === 'ES_SCHEDULED' ? (hold ? L('Sending…') : L('Scheduled')) : (sent ? L('Sent') : (sendError ? L('Not sent yet: it waits in the Outbox') + ' (' + sendError + ')' : L('Sending…')))
} else {
    mode = 'internal'
    if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
    // a send queued offline and sent again after a lost answer: once per clientRef, answering the first send.
    // Claimed before anything is made, in this transaction (run#Operation's: a mutation), so a send that fails keeps no claim
    const SEND_REF = 'ironstone.comms.ComposeServices.send#Compose:internal'
    const ref = clientRef != null && clientRef !== '' ? String(clientRef) : null
    if (ref) {
        const claim = ec.service.sync().name('org.moqui.edge.ClientSyncServices.claim#ClientRequest').parameters({clientRef: ref, serviceName: SEND_REF}).call()
        if (ec.message.hasError()) return
        if (claim.duplicate) {
            // the ref's row locked, and its answer read again under the lock, so an overlapping resend sees this one's
            const row = ec.entity.find('moqui.basic.client.ClientRequestRef').condition({userId: ec.user.userId, serviceName: SEND_REF, clientRef: ref})
                    .forUpdate(true).disableAuthz().one()
            let kept = claim.result || {}
            try { kept = row?.resultJson ? JSON.parse(row.resultJson) : kept } catch (err) { kept = claim.result || {} }
            const keptIds = Array.from(kept.communicationEventIdList || []).map(String)
            const live = keptIds.length ? Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', 'in', keptIds)
                    .condition('statusId', 'not-equals', 'CeCancelled').selectField('communicationEventId').selectField('statusId').disableAuthz().list()) : []
            if (live.length) {
                // the first send's messages, as they are now
                communicationEventIdList = keptIds
                sent = true
                statusId = live[0].statusId || 'CeReceived'
                message = L('Sent')
                duplicate = true
                return
            }
            // every message of the first send was taken back (Undo) or is gone: this send goes, and its answer replaces the ref's
        }
    }
    const resolve = (json) => {
        const out = ec.service.sync().name('ironstone.comms.ComposeServices.resolve#Recipients').parameters({chipsJson: json || '[]', mode: 'internal'}).call()
        return ec.message.hasError() ? null : out
    }
    const toOut = resolve(toJson)
    if (toOut == null) return
    const ccOut = resolve(ccJson)
    if (ccOut == null) return
    // the user's own uploads only
    let uploads = []
    if (uploadsJson) { try { uploads = JSON.parse(uploadsJson) } catch (err) { ec.message.addError('The attachments are not JSON'); return } }
    // the user's own uploads: the BasicComms composer's (dbresource://comms/compose/) or IronStone's earlier ones
    const prefixes = [`dbresource://comms/compose/${ec.user.userId}/`, `dbresource://ironstone/compose/${ec.user.userId}/`]
    for (const upload of Array.from(uploads || [])) {
        if (!upload || !prefixes.some((prefix) => String(upload.location || '').startsWith(prefix)) || String(upload.location).includes('..')) {
            ec.message.addError(L('Attachment not found') + ': ' + (upload?.name || '')); return }
    }
    const html = String(body || '') + (quoteHtml ? String(quoteHtml) : '')
    const cleaned = StringUtilities.cleanHtml(html)
    const toIds = toOut.partyIdList.filter((id) => id !== partyId)
    const ccIds = ccOut.partyIdList.filter((id) => id !== partyId && !toIds.includes(id))
    const mailboxes = Array.from(new Set(toOut.contactListIdList.concat(ccOut.contactListIdList)))
    const made = []
    if (parentCommEventId) {
        const out = ec.service.sync().name('mantle.party.CommunicationServices.reply#CommunicationEvent').parameters({parentCommEventId: parentCommEventId,
            fromPartyId: partyId, subject: subject || null, body: cleaned, contentType: 'text/html', replyToSenderOnly: replyToSenderOnly === true,
            toPartyIdList: toIds, ccPartyIdList: ccIds}).call()
        if (ec.message.hasError()) return
        made.push(out.communicationEventId)
    } else {
        if (toIds.length === 0 && ccIds.length === 0 && mailboxes.length === 0) { ec.message.addError(L('Add a recipient in To')); return }
        if (mailboxes.length === 0) {
            const out = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({communicationEventTypeId: 'Message',
                fromPartyId: partyId, toPartyIdList: toIds, ccPartyIdList: ccIds, subject: subject || null, body: cleaned, contentType: 'text/html',
                contactMechTypeEnumId: 'CmtWebForm', entryDate: ec.user.nowTimestamp}).call()
            if (ec.message.hasError()) return
            made.push(out.communicationEventId)
        }
        // a post in each mailbox, the named recipients on the first
        mailboxes.forEach((listId, index) => {
            if (ec.message.hasError()) return
            const out = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({communicationEventTypeId: 'Message',
                fromPartyId: partyId, contactListId: listId, toPartyIdList: index === 0 ? toIds : [], ccPartyIdList: index === 0 ? ccIds : [],
                subject: subject || null, body: cleaned, contentType: 'text/html', contactMechTypeEnumId: 'CmtWebForm', entryDate: ec.user.nowTimestamp}).call()
            if (!ec.message.hasError()) made.push(out.communicationEventId)
        })
        if (ec.message.hasError()) return
    }
    for (const eventId of made) {
        Array.from(uploads || []).forEach((upload, index) => {
            ec.service.sync().name('create#mantle.party.communication.CommunicationEventContent').parameters({communicationEventId: eventId,
                contentLocation: upload.location, description: upload.name || String(upload.location).split('/').pop(), sequenceNum: index + 1,
                contentDate: ec.user.nowTimestamp}).call()
        })
        if (ec.message.hasError()) return
        if (record) {
            ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord').parameters({communicationEventId: eventId,
                recordEntityName: record.recordEntityName, recordId: record.recordId, notifyFollowers: true}).call()
            if (ec.message.hasError()) return
        }
    }
    communicationEventIdList = made
    sent = true
    statusId = 'CeReceived'
    message = L('Sent')
    if (ref) ec.service.sync().name('org.moqui.edge.ClientSyncServices.store#ClientRequest').parameters({clientRef: ref, serviceName: SEND_REF,
        result: {mode: mode, communicationEventIdList: made, sent: true, statusId: statusId, message: message}}).call()
    if (ec.message.hasError()) return
}
// Send and archive: the thread answered leaves the Inbox
if (archiveThread && threadStore && threadId) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('ironstone.comms.InboxServices.set#ThreadState').parameters({targetList: [{store: threadStore, threadId: threadId}], action: 'archive'}).call()
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

if (emailMessageId) {
    const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.cancel#ScheduledSend').parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    statusId = out.statusId
    return
}
let ids = communicationEventIdList ? Array.from(communicationEventIdList) : []
if (!ids.length && communicationEventIdsJson) { try { ids = JSON.parse(communicationEventIdsJson) } catch (err) { ids = [] } }
const partyId = ec.user.userAccount?.partyId
const nowMillis = Number(String(ec.user.nowTimestamp))
for (const id of ids) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', id).disableAuthz().one()
    if (event == null || event.fromPartyId !== partyId) { ec.message.addError(`Communication event ${id} not found`); return }
    if (nowMillis - Number(String(event.entryDate)) > 120000) { ec.message.addError(ec.l10n.localize('It is too late to undo this message')); return }
    event.set('statusId', 'CeCancelled')
    event.update()
}
statusId = 'CeCancelled'
